window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-251e96fe9c5079cf"]={"versions": [{"id": "FIG-251e96fe9c5079cf", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd E2E_Receiver I-PDU</code>) im Kontext der AUTOSAR Classic Platform E2E Library (<code>AUTOSAR_SWS_E2ELibrary</code>). Es stellt den empfängerseitigen Prüfablauf für Datenintegrität auf I-PDU- bzw. Signalgruppenebene dar, einschließlich des Zusammenspiels zwischen Datenempfänger, E2E Library, CRC Library und dem PDU Router.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert vier Entitäten bzw. Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>Receiver of I-PDUs</code>: Aufrufende Empfängereinheit / COM-Schicht bzw. Software-Komponente.</li>\n<li><code>E2E Library</code>: AUTOSAR-Basissoftware-Bibliothek zur End-to-End-Absicherung.</li>\n<li><code>CRC Library</code>: Hilfsbibliothek zur zyklischen Redundanzprüfung.</li>\n<li><code>«module» PduR</code>: AUTOSAR PDU Router als PDU-Bereitsteller.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Datenelemente:</p>\n<ul class=\"fig-list\">\n<li><code>read I-PDU :Read_Status</code>: Leseoperation vom PduR mit Rückgabe des Lesestatus.</li>\n<li><code>Config</code>: Konfigurationsstruktur für das E2E-Profil (hier Profil 1).</li>\n<li><code>State</code>: Zustandsstruktur mit Feldern wie <code>NewDataAvailable</code>.</li>\n<li><code>Data</code>: Typisiert als <code>(uint8*) I-PDU</code>.</li>\n<li><code>E2E_P01Check(Config, State, Data)</code>: Prüffunktion der E2E Library mit Rückgabewert <code>ret</code>.</li>\n<li><code>Crc_CalculateCRCx</code>: CRC-Berechnungsfunktion der CRC Library.</li>\n<li>DEM (Diagnostic Event Manager) zur Fehlerberichterstattung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Sequenzablauf vollzieht sich schrittweise:</p>\n<ol class=\"fig-list\">\n<li><code>[At Receiver startup]</code>: Der Empfänger instantiiert und initialisiert intern die Strukturen <code>Config</code> und <code>State</code>.</li>\n<li>Empfang: Der Empfänger ruft synchron <code>read I-PDU</code> am <code>PduR</code> auf und erhält <code>:Read_Status</code>.</li>\n<li>Zustandsaktualisierung: Der Empfänger setzt intern <code>State-&gt;NewDataAvailable = TRUE</code>.</li>\n<li>Datenpufferung: Der Empfänger castet bzw. puffert <code>Data = (uint8*) I-PDU</code>.</li>\n<li>Prüfaufruf: Der Empfänger ruft <code>E2E_P01Check(Config, State, Data)</code> an der <code>E2E Library</code> auf.</li>\n<li>Bibliotheksausführung:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>E2E Library</code> prüft die Kontrollfelder (<code>Execute library logic, e.g. check all control fields</code>).</li>\n<li>Für E2E Profile 1 und 2 ruft sie synchron <code>Crc_CalculateCRCx</code> an der <code>CRC Library</code> zur CRC-Berechnung auf.</li>\n<li>Sie aktualisiert die Zustandsstruktur intern (<code>update State depending on checks</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Rückkehr: Die Funktion gibt den Statuscode <code>ret</code> synchron an den Empfänger zurück.</li>\n<li>Nachbereitung:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger evaluiert <code>ret</code> und meldet interne Fehler ggf. an das DEM (<code>Evaluate ret and handle library internal errors, e.g. report to DEM</code>).</li>\n<li>Bei erfolgreicher Prüfung aktualisiert der Empfänger die Signale aus dem I-PDU-Inhalt (<code>Update signals with the content from I-PDU</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm zeigt ein beispielhaftes Integrations- und Aufrufschema (hier anhand von E2E Profile 1 mit <code>E2E_P01Check</code>). Die E2E-Bibliothek ist zustandslos bezüglich statischer Variablen; der Zustand wird vollständig in der vom Aufrufer bereitgestellten <code>State</code>-Struktur geführt. Die Übergabe der Nutzdaten erfolgt als Bytezeiger <code>uint8*</code>. Die Auswertung des Rückgabewertes <code>ret</code> sowie die Entscheidung über die Weiterverarbeitung oder das Verwerfen der Daten (Signalupdate) obliegt dem Empfänger.</p>"}, {"id": "FIG-c46365853f4dec6f", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm im Kontext der AUTOSAR Classic Platform E2E Library (<code>AUTOSAR_SWS_E2ELibrary</code>). Es stellt den empfängerseitigen Prüfablauf für Datenintegrität auf I-PDU- bzw. Signalgruppenebene dar, einschließlich des Zusammenspiels zwischen Datenempfänger, E2E Library, CRC Library und dem PDU Router.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert vier Entitäten bzw. Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>Receiver of I-PDUs</code>: Aufrufende Empfängereinheit / COM-Schicht bzw. Software-Komponente.</li>\n<li><code>E2E Library</code>: AUTOSAR-Basissoftware-Bibliothek zur End-to-End-Absicherung.</li>\n<li><code>CRC Library</code>: Hilfsbibliothek zur zyklischen Redundanzprüfung.</li>\n<li><code>«module» PduR</code>: AUTOSAR PDU Router als PDU-Bereitsteller.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Datenelemente:</p>\n<ul class=\"fig-list\">\n<li><code>read I-PDU :Read_Status</code>: Leseoperation vom PduR mit Rückgabe des Lesestatus.</li>\n<li><code>Config</code>: Konfigurationsstruktur für das E2E-Profil (hier Profil 1).</li>\n<li><code>State</code>: Zustandsstruktur mit Feldern wie <code>NewDataAvailable</code>.</li>\n<li><code>Data</code>: Typisiert als <code>(uint8*) I-PDU</code>.</li>\n<li><code>E2E_P01Check(Config, State, Data)</code>: Prüffunktion der E2E Library mit Rückgabewert <code>ret</code>.</li>\n<li><code>Crc_CalculateCRCx</code>: CRC-Berechnungsfunktion der CRC Library.</li>\n<li>DEM (Diagnostic Event Manager) zur Fehlerberichterstattung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Sequenzablauf vollzieht sich schrittweise:</p>\n<ol class=\"fig-list\">\n<li><code>[At Receiver startup]</code>: Der Empfänger instantiiert und initialisiert intern die Strukturen <code>Config</code> und <code>State</code>.</li>\n<li>Empfang: Der Empfänger ruft synchron <code>read I-PDU</code> am <code>PduR</code> auf und erhält <code>:Read_Status</code>.</li>\n<li>Zustandsaktualisierung: Der Empfänger setzt intern <code>State-&gt;NewDataAvailable = TRUE</code>.</li>\n<li>Datenpufferung: Der Empfänger castet bzw. puffert <code>Data = (uint8*) I-PDU</code>.</li>\n<li>Prüfaufruf: Der Empfänger ruft <code>E2E_P01Check(Config, State, Data)</code> an der <code>E2E Library</code> auf.</li>\n<li>Bibliotheksausführung:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>E2E Library</code> prüft die Kontrollfelder (<code>Execute library logic, e.g. check all control fields</code>).</li>\n<li>Für E2E Profile 1 und 2 ruft sie synchron <code>Crc_CalculateCRCx</code> an der <code>CRC Library</code> zur CRC-Berechnung auf.</li>\n<li>Sie aktualisiert die Zustandsstruktur intern (<code>update State depending on checks</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Rückkehr: Die Funktion gibt den Statuscode <code>ret</code> synchron an den Empfänger zurück.</li>\n<li>Nachbereitung:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger evaluiert <code>ret</code> und meldet interne Fehler ggf. an das DEM (<code>Evaluate ret and handle library internal errors, e.g. report to DEM</code>).</li>\n<li>Bei erfolgreicher Prüfung aktualisiert der Empfänger die Signale aus dem I-PDU-Inhalt (<code>Update signals with the content from I-PDU</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm zeigt ein beispielhaftes Integrations- und Aufrufschema (hier anhand von E2E Profile 1 mit <code>E2E_P01Check</code>). Die E2E-Bibliothek ist zustandslos bezüglich statischer Variablen; der Zustand wird vollständig in der vom Aufrufer bereitgestellten <code>State</code>-Struktur geführt. Die Übergabe der Nutzdaten erfolgt als Bytezeiger <code>uint8*</code>. Die Auswertung des Rückgabewertes <code>ret</code> sowie die Entscheidung über die Weiterverarbeitung oder das Verwerfen der Daten (Signalupdate) obliegt dem Empfänger.</p>"}], "trans": [{"from": "FIG-251e96fe9c5079cf", "to": "FIG-c46365853f4dec6f", "fr": "R3.2.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Diagrammrahmen: Der äußere UML-Rahmen mit dem Bezeichner-Tag <code>sd E2E_Receiver I-PDU</code> wurde entfernt.</li>\n<li>PduR-Kopfzeile: Das Modul-Dekorationssymbol (zwei verbundene Kreise unten rechts im Kasten) wurde entfernt.</li>\n<li>Layout: Weißraum und Abstände zwischen den Lebenslinien und Beschriftungen wurden neu gesetzt.</li>\n</ul>"}]};
